10725: # (wave 26b, D10) The operator's kick file of the run with handoff number $Nn:
10726: # <task>/.consult.kick-<NN> - written by `-Kick -Member <NN>` (from another shell), polled by the
10727: # run while its engine turn runs; the run deletes it once the turn's process tree is stopped (the
10728: # acknowledgement -Kick waits for). A `.consult.*` file: outside the tree check.
10729: function Get-KickPath {
10730:     param([string]$TaskDir, [string]$Nn)
10731:     return (Join-Path $TaskDir ".consult.kick-$Nn")
10732: }
10733: 
10734: # (wave 27c, D1 / F30-1, F29-2, F32-1, F30-6) The kick protocol, per REQUEST: the kick file and its
10735: # acknowledgement are small JSON records { id (a GUID), when, pid[, result] }. Read-KickRecord reads
10736: # one tolerantly: { Exists; Id ('' for an older plain-text file); Result; When ($null when unknown -
10737: # then the file's own write time counts) }.
10738: function Read-KickRecord {
10739:     param([string]$Path)
10740:     $r = [pscustomobject]@{ Exists = $false; Id = ''; Result = ''; When = $null }
10741:     if (-not $Path -or -not [IO.File]::Exists($Path)) { return $r }
10742:     $r.Exists = $true
10743:     $text = Read-SharedText -Path $Path
10744:     try {
10745:         $o = ConvertFrom-Json -InputObject $text
10746:         if (Test-IsJsonObject $o) {
10747:             $r.Id = [string](Get-PropertyValue $o 'id' '')
10748:             $r.Result = [string](Get-PropertyValue $o 'result' '')
10749:             $r.When = ConvertTo-WhenOffset (Get-PropertyValue $o 'when' '')
10750:         }
10751:     } catch {
10752:         # an older plain-text record: "kicked <iso> ..." / "late <iso> ..."
10753:         if ($text -match '^(kicked|late)\b') { $r.Result = $(if ($Matches[1] -eq 'late') { 'late' } else { 'stopped' }) }
10754:     }
10755:     if ($null -eq $r.When) { try { $r.When = [DateTimeOffset]([IO.File]::GetLastWriteTimeUtc($Path)) } catch { } }
10756:     return $r
10757: }
