8625: # without following links (FileSystemInfo.Attributes is the link's own).
8626: function Get-RoleFileProblem {
8627:     param([string]$Path, [string]$Root)
8628:     $sep = [IO.Path]::DirectorySeparatorChar
8629:     $cmp = $(if ($sep -eq '\') { [StringComparison]::OrdinalIgnoreCase } else { [StringComparison]::Ordinal })
8630:     $rootFull = [IO.Path]::GetFullPath($Root).TrimEnd('\', '/')
8631:     $full = [IO.Path]::GetFullPath($Path)
8632:     if (-not $full.StartsWith($rootFull + $sep, $cmp)) { return "'$Path' is outside '$rootFull'" }
8633:     $fi = New-Object IO.FileInfo($full)
8634:     $di = New-Object IO.DirectoryInfo($full)
8635:     if (-not $fi.Exists -and -not $di.Exists) {
8636:         # a dangling link reports neither; its attributes still read
8637:         $attr = $null
8638:         try { $attr = [IO.File]::GetAttributes($full) } catch { $attr = $null }
8639:         if ($null -eq $attr) { return '' }
8640:         return "'$full' is not a regular file (attributes $attr)"
8641:     }
8642:     if ($di.Exists) { return "'$full' is a directory$(if (($di.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { ' link (reparse point)' }), not a regular file" }
8643:     if (($fi.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { return "'$full' is a symbolic link or another reparse point, not a regular file" }
8644:     $dir = $fi.Directory
8645:     while ($dir) {
8646:         if (($dir.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { return "the directory '$($dir.FullName)' is a junction or symbolic link (reparse point)" }
8647:         if ([string]::Equals($dir.FullName.TrimEnd('\', '/'), $rootFull, $cmp)) { break }
